1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	export interface Item {
6	  type: string;
7	  material?: string;
8	  enchantment?: number;
9	  cursed?: boolean;
10	}
11	
12	export interface QuoteStep {
13	  op: "quote";
14	  items: Item[];
15	}
16	
17	export interface Damage {
18	  itemType: string;
19	  amount: number;
20	}
21	
22	export interface ClaimStep {
23	  op: "claim";
24	  policy: number;
25	  incident: { cause: string; damages: Damage[] };
26	}
27	
28	export type Step = QuoteStep | ClaimStep;
29	
30	export interface Scenario {
31	  customer: Customer;
32	  steps: Step[];
33	}
34	
35	export type StepResult = { premium: number } | { payout: number; remainingCap: number };
36	
37	export interface ScenarioResult {
38	  results: StepResult[];
39	}
40	
41	const PROCESSING_FEE = 5;
42	const INITIAL_ASSESSMENT_SURCHARGE = 0.1;
43	const CURSE_SURCHARGE = 0.5;
44	const HIGH_ENCHANTMENT_LEVEL = 5;
45	const HIGH_ENCHANTMENT_SURCHARGE = 0.3;
46	const LOYALTY_YEARS = 2;
47	const LOYALTY_DISCOUNT = 0.2;
48	const FOLLOW_UP_CONTRACT_DISCOUNT = 0.15;
49	
50	const BASE_PREMIUMS: Record<string, number> = {
51	  sword: 100,
52	  amulet: 60,
53	  staff: 80,
54	  potion: 40,
55	  rune: 25,
56	  moonstone: 25,
57	};
58	
59	const INSURANCE_VALUES: Record<string, number> = {
60	  sword: 1000,
61	  amulet: 600,
62	  staff: 800,
63	  potion: 400,
64	  rune: 250,
65	  moonstone: 250,
66	};
67	
68	/** Premiums round up: fractions of a Gold piece go to the MHPCO, never the customer. */
69	const roundPremiumInMHPCOFavour = (amount: number): number => Math.ceil(amount);
70	
71	const COMPONENT_BLOCK_SIZE = 3;
72	const COMPONENT_BLOCK_PREMIUM = 60;
73	
74	const countsByType = (items: Item[]): Map<string, number> =>
75	  items.reduce(
76	    (counts, item) => counts.set(item.type, (counts.get(item.type) ?? 0) + 1),
77	    new Map<string, number>(),
78	  );
79	
80	const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
81	
82	/** Exactly three alike components form a building block, priced at a flat rate. */
83	const basePremiumForAlikeItems = (type: string, count: number): number =>
84	  COMPONENT_TYPES.has(type) && count === COMPONENT_BLOCK_SIZE
85	    ? COMPONENT_BLOCK_PREMIUM
86	    : count * BASE_PREMIUMS[type];
87	
88	const policyBasePremium = (items: Item[]): number =>
89	  [...countsByType(items)].reduce(
90	    (total, [type, count]) => total + basePremiumForAlikeItems(type, count),
91	    0,
92	  );
93	
94	/**
95	 * Applies a rate to the amount it is measured against. Rates never compound:
96	 * premium modifiers all measure against the same base premium and are summed,
97	 * and a reimbursement rate measures against the damage amount.
98	 */
99	const amountOf = (rate: number, measuredAgainst: number): number => rate * measuredAgainst;
100	
101	/** Item-specific surcharge rates stack additively on the item's own base premium. */
102	const surchargeRateFor = (item: Item): number =>
103	  (item.cursed ? CURSE_SURCHARGE : 0) +
104	  ((item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL ? HIGH_ENCHANTMENT_SURCHARGE : 0);
105	
106	/** Item-specific surcharges are rates on the affected item's own base premium. */
107	const itemSurchargeAmount = (items: Item[]): number =>
108	  items.reduce(
109	    (total, item) => total + amountOf(surchargeRateFor(item), BASE_PREMIUMS[item.type]),
110	    0,
111	  );
112	
113	/**
114	 * The facts a policy-wide rate is measured against. Rates key on different
115	 * things — loyalty on the customer's history, the assessment/follow-up rate on
116	 * where the quote falls in the scenario — so they travel together as context.
117	 */
118	interface PolicyContext {
119	  customer: Customer;
120	  /** Zero-based position of this quote among the scenario's quotes. */
121	  quoteOrdinal: number;
122	}
123	
124	/** Policy-wide rates apply to the policy base premium; discounts are negative. */
125	const policyRateFor = ({ customer, quoteOrdinal }: PolicyContext): number =>
126	  INITIAL_ASSESSMENT_SURCHARGE +
127	  (customer.yearsWithMHPCO >= LOYALTY_YEARS ? -LOYALTY_DISCOUNT : 0) +
128	  (quoteOrdinal > 0 ? -FOLLOW_UP_CONTRACT_DISCOUNT : 0);
129	
130	const quote = (step: QuoteStep, policy: PolicyContext): StepResult => {
131	  const base = policyBasePremium(step.items);
132	  const modifiers = itemSurchargeAmount(step.items) + amountOf(policyRateFor(policy), base);
133	  return {
134	    premium: roundPremiumInMHPCOFavour(base + modifiers + PROCESSING_FEE),
135	  };
136	};
137	
138	const isQuote = (step: Step): step is QuoteStep => step.op === "quote";
139	
140	const DEDUCTIBLE_PER_DAMAGE = 100;
141	const CAP_MULTIPLIER = 2;
142	
143	/** Payouts round down: fractions of a Gold piece stay with the MHPCO. */
144	const roundPayoutInMHPCOFavour = (amount: number): number => Math.floor(amount);
145	
146	const SEVERE_ENCHANTMENT_LEVEL = 8;
147	const SEVERE_ENCHANTMENT_REIMBURSEMENT = 0.5;
148	const FULL_REIMBURSEMENT = 1;
149	
150	/**
151	 * Damage to a heavily enchanted item is reimbursed at half its amount;
152	 * everything else — including the price list's dragon-material clause, which
153	 * grants full reimbursement — is reimbursed in full. Where both clauses apply
154	 * the half rate wins, so the enchantment level alone decides the rate.
155	 */
156	const reimbursementRateFor = (item: Item): number =>
157	  (item.enchantment ?? 0) >= SEVERE_ENCHANTMENT_LEVEL
158	    ? SEVERE_ENCHANTMENT_REIMBURSEMENT
159	    : FULL_REIMBURSEMENT;
160	
161	const countOfType = (type: string, of: { type: string }[]): number =>
162	  of.filter((candidate) => candidate.type === type).length;
163	
164	/**
165	 * A claim can run out of insured items either because the policy covers none of
166	 * that type at all, or because it covers fewer than the claim names.
167	 */
168	const overClaimMessage = (type: string, damages: Damage[], items: Item[]): string => {
169	  const insured = countOfType(type, items);
170	  if (insured === 0) return `Policy does not cover a ${type}`;
171	  const claimed = countOfType(type, damages.map((damage) => ({ type: damage.itemType })));
172	  return `Claim damages ${claimed} ${type}s but the policy insures only ${insured} ${type}`;
173	};
174	
175	/** A damage entry together with the specific insured item it claims against. */
176	interface ClaimedDamage {
177	  damage: Damage;
178	  item: Item;
179	}
180	
181	/**
182	 * A damage entry names its item only by type, so pairing is positional within a
183	 * type: the policy may insure several items of one type, and each damage entry
184	 * claims against a distinct one. Pairing therefore happens for the damage list
185	 * as a whole — an item already claimed against is no longer available to the
186	 * next entry, which is what makes over-claiming detectable.
187	 */
188	const claimsAgainstInsuredItems = (damages: Damage[], items: Item[]): ClaimedDamage[] => {
189	  const unclaimed = [...items];
190	  return damages.map((damage) => {
191	    const index = unclaimed.findIndex((item) => item.type === damage.itemType);
192	    if (index < 0) throw new Error(overClaimMessage(damage.itemType, damages, items));
193	    return { damage, item: unclaimed.splice(index, 1)[0] };
194	  });
195	};
196	
197	/** A policy issued by a quote step, tracking how much of its cap remains. */
198	interface Policy {
199	  items: Item[];
200	  remainingCap: number;
201	}
202	
203	const insuranceSum = (items: Item[]): number =>
204	  items.reduce((sum, item) => sum + INSURANCE_VALUES[item.type], 0);
205	
206	const openPolicy = (items: Item[]): Policy => ({
207	  items,
208	  remainingCap: CAP_MULTIPLIER * insuranceSum(items),
209	});
210	
211	/** Every damage entry carries its own deductible, applied after any clause. */
212	const payoutForDamage = ({ damage, item }: ClaimedDamage): number =>
213	  amountOf(reimbursementRateFor(item), damage.amount) - DEDUCTIBLE_PER_DAMAGE;
214	
215	/** What the damages come to on their own, before the policy's cap limits it. */
216	const payoutBeforeCap = (damages: Damage[], items: Item[]): number =>
217	  claimsAgainstInsuredItems(damages, items).reduce(
218	    (total, claimed) => total + payoutForDamage(claimed),
219	    0,
220	  );
221	
222	/**
223	 * Settling a claim pays out and draws the policy's cap down by that amount, so
224	 * it yields both the result and the policy as it stands afterwards.
225	 */
226	const settleClaim = (
227	  step: ClaimStep,
228	  policy: Policy,
229	): { result: StepResult; policy: Policy } => {
230	  const payout = Math.min(
231	    roundPayoutInMHPCOFavour(payoutBeforeCap(step.incident.damages, policy.items)),
232	    policy.remainingCap,
233	  );
234	  const remainingCap = policy.remainingCap - payout;
235	  return { result: { payout, remainingCap }, policy: { ...policy, remainingCap } };
236	};
237	
238	export const runScenario = (scenario: Scenario): ScenarioResult => {
239	  /** A claim names its policy by the index of the quote step that opened it. */
240	  const policiesByQuoteStep = new Map<number, Policy>();
241	  const results = scenario.steps.map((step, index) => {
242	    if (isQuote(step)) {
243	      const context = {
244	        customer: scenario.customer,
245	        quoteOrdinal: policiesByQuoteStep.size,
246	      };
247	      policiesByQuoteStep.set(index, openPolicy(step.items));
248	      return quote(step, context);
249	    }
250	    const policy = policiesByQuoteStep.get(step.policy);
251	    if (!policy) throw new Error(`No policy created by step ${step.policy}`);
252	    const settled = settleClaim(step, policy);
253	    policiesByQuoteStep.set(step.policy, settled.policy);
254	    return settled.result;
255	  });
256	  return { results };
257	};
