const countOfType = (type: string, of: { type: string }[]): number =>
  of.filter((candidate) => candidate.type === type).length;

/**
 * A claim can run out of insured items either because the policy covers none of
 * that type at all, or because it covers fewer than the claim names.
 */
const overClaimMessage = (type: string, damages: Damage[], items: Item[]): string => {
  const insured = countOfType(type, items);
  if (insured === 0) return `Policy does not cover a ${type}`;
  const claimed = countOfType(type, damages.map((damage) => ({ type: damage.itemType })));
  return `Claim damages ${claimed} ${type}s but the policy insures only ${insured} ${type}`;
};

